#!/usr/bin/env node
/**
 * Regenerate the template's generated files from this repository's Interlude sources.
 *
 * `template/web/lib/abi.ts` is Clicker's ABI, and Clicker inherits Delegatable, so any function
 * added to Delegatable (ownership hand-over, say) changes it. `test/template-forge.test.js`
 * fails until this is run. The output format is exactly `interlude abi`'s, so a user running
 * `npm run abi` in a fresh scaffold gets a byte-identical file.
 *
 * `ClickerInterludeSurface.sol` is not regenerated here: it depends only on Clicker's own storage
 * layout, which Delegatable's namespaced storage never moves. After editing Clicker's state,
 * regenerate it with the CLI from a scaffold (`INTERLUDE_CONTRACTS=<repo>/packages/contracts/src
 * interlude gen --contract Clicker`) and copy it back; `interlude check` there proves it.
 *
 * Needs forge on PATH. Touches only template/web/lib/abi.ts.
 */

import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { scaffold, templateDir } from "../src/scaffold.js";

const repoContracts = fileURLToPath(new URL("../../contracts/src/", import.meta.url));
const scratch = mkdtempSync(join(tmpdir(), "create-interlude-app sync "));

try {
  const project = scaffold({ dir: join(scratch, "sync"), name: "sync" }).dir;
  const contracts = join(project, "contracts");
  writeFileSync(join(contracts, "remappings.txt"), `@interludelayer/contracts/=${repoContracts}\n`);

  const build = spawnSync("forge", ["build"], { cwd: contracts, encoding: "utf8" });
  if (build.status !== 0) {
    process.stderr.write(build.stdout + build.stderr);
    process.exit(1);
  }

  const { abi } = JSON.parse(
    readFileSync(join(contracts, "out", "Clicker.sol", "Clicker.json"), "utf8"),
  );
  // Same text as the CLI's abiModule(), so `npm run abi` in a scaffold changes nothing.
  const module =
    `// Generated by @interludelayer-sdk/cli from Clicker's compiled ABI.\n` +
    `// Do not edit: \`interlude abi --contract Clicker\` rewrites it.\n` +
    `export const abi = ${JSON.stringify(abi, null, 2)} as const;\n`;

  const target = join(templateDir(), "web", "lib", "abi.ts");
  const before = readFileSync(target, "utf8");
  writeFileSync(target, module);
  process.stdout.write(
    before === module
      ? `template/web/lib/abi.ts already matches (${abi.length} entries)\n`
      : `rewrote template/web/lib/abi.ts (${abi.length} entries)\n`,
  );
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
